  "newer": [
    {
      "code": "202104231756150811",
      "date": "23-04-2021",
      "what_changed": "Ended the empanelment and rates under the 29 Jan 2018 policy by directing all future cloud service procurement through the GeM portal after 30 Apr 2021, with ongoing services rates expiring 15 Jun 2021."
    },
    {
      "code": "201906191741481211",
      "date": "19-06-2019",
      "what_changed": "Extended the migration deadline for existing applications to cloud from 30.10.2018 to 31.03.2020, added mandatory website and application security audit, and authorized DIT PIC for CSP selection."
    },
    {
      "code": "201907051642210511",
      "date": "05-07-2019",
      "what_changed": "Extended operational instructions by requiring departments to define and communicate data to be migrated/hosted, confirm data for archival, verify datasets for automated removal from online to archival, and periodically review cloud applications and data for cost-effective efficiency."
    }
  ],
  "cited": [
    {
      "code": "201801291824268911",
      "date": "29-01-2018",
      "title": "Cloud Computing Policy- Instructions to Departments regarding hosting of IT applications",
      "quote": "The following instructions are issued in supersession of all earlier instructions issued in this regard.",
      "page": 1
    },
    {
      "code": "201801291824268911",
      "date": "29-01-2018",
      "title": "Cloud Computing Policy- Instructions to Departments regarding hosting of IT applications",
      "quote": "In case of existing applications not hosted in a cloud environment, Government organizations must ensure that the applications are migrated to cloud on or before 30.10.2018.",
      "page": 1
    },
    {
      "code": "202104231756150811",
      "date": "23-04-2021",
      "title": "Cloud Computing policy  Empanelment of Cloud Service Providers and Guidelines for Government Organizations.",
      "quote": "सदर Empanelment आणि जाहीर करण्यात आलेले सेवा दर दिनांक ३० एप्रिल, २०२१ रोजी संपुष्टात येत आहेत.",
      "page": 1
    },
    {
      "code      ": "202104231756150811",
      "date": "23-04-2021",
      "title": "Cloud Computing policy  Empanelment of Cloud Service Providers and Guidelines for Government Organizations.",
      "quote": "आता क्लाऊड सेवा केंद्र शासनामार्फत GeM पोर्टल वर उपलब्ध करुन देण्यात आलेली आहे.",
      "page": 1
    },
    {
      "code": "201906191741481211",
      "date": "19-06-2019",
      "title": "Cloud Computing Policy- Instructions to Departments regarding hosting of IT applications.",
      "quote": "In case of existing applications not hosted in a cloud environment, Government organizations must ensure that the applications are migrated to cloud on or before 31.03.2020.",
      "page": 1
    }
  ],
  "answer": "No, the 29 January 2018 cloud computing circular is not current as a standalone instrument; it was superseded by later instructions. Earlier, it required migration of existing applications to the cloud by 30.10.2018. Further, an addendum dated 19-06-2019 extended that migration deadline to 31.03.2020, and a GR dated 23-04-2021 ended the empanelment and rates under the 29 January 2018 policy by directing procurement through the GeM portal after 30.04.2021.",
  "status": "answered"
}

